    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]

    # Partition the occupied shape into 2x2 squares and L-triominoes.
    def solve(rem):
        if not rem:
            return []
        r, c = min(rem)
        placements = []
        for rr in range(max(0, r - 1), min(h - 1, r) + 1):
            for cc in range(max(0, c - 1), min(w - 1, c) + 1):
                sq = {(rr, cc), (rr + 1, cc), (rr, cc + 1), (rr + 1, cc + 1)}
                if (r, c) in sq and sq <= rem:
                    placements.append((sq, 1))
        for rr in range(max(0, r - 2), min(h - 1, r) + 1):
            for cc in range(max(0, c - 2), min(w - 1, c) + 1):
                block = {(y, x) for y in range(rr, rr + 2) for x in range(cc, cc + 2)}
                for missing in block:
                    tri = block - {missing}
                    if (r, c) in tri and tri <= rem:
                        # Give the three L orientations distinct colors.
                        color = 2 + ((missing[0] + missing[1]) % 3)
                        placements.append((tri, color))
        for piece, color in placements:
            rest = solve(rem - piece)
            if rest is not None:
                return [(piece, color)] + rest
        return None

    tiling = solve(cells)
    if tiling is None:
        for r, c in cells:
            out[r][c] = 1
    else:
        for piece, color in tiling:
            for r, c in piece:
                out[r][c] = color
    return out
