def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}

    # Exact-cover the shape with 2x2 squares and L-triominoes.
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            pieces.append((block, 1))
            for missing, color in (
                ((r, c), 2),       # missing top-left
                ((r, c + 1), 4),   # missing top-right
                ((r + 1, c), 3),   # missing bottom-left
                ((r + 1, c + 1), 5),
            ):
                pieces.append((block - {missing}, color))

    by_cell = {cell: [] for cell in occupied}
    for piece, color in pieces:
        if piece <= occupied:
            for cell in piece:
                by_cell[cell].append((piece, color))

    def search(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for piece, color in by_cell[cell]:
            if piece <= remaining:
                rest = search(remaining - piece)
                if rest is not None:
                    return [(piece, color)] + rest
        return None

    tiling = search(occupied)
    out = [[0] * w for _ in range(h)]
    if tiling:
        for piece, color in tiling:
            for r, c in piece:
                out[r][c] = color
    return out
